    ffi.Pointer<UaBuffer>,
    ffi.Pointer<UaBuffer>,
  )
>(symbol: 'ua_verify')
external int _ua_verify(
  UaBytes signature,
  ffi.Pointer<UaNamedBytes> data,
  int data_count,
  ffi.Pointer<UaBytes> trust_anchors,
  int trust_anchors_count,
  ffi.Pointer<UaBytes> certificates,
  int certificates_count,
  bool is_online,
  ffi.Pointer<UaBuffer> report_json,
  ffi.Pointer<UaBuffer> error_message,
);

UaStatus ua_verify(
  UaBytes signature,
  ffi.Pointer<UaNamedBytes> data,
  int data_count,
  ffi.Pointer<UaBytes> trust_anchors,
  int trust_anchors_count,
