const int UA_CURVE_BASIS_OPTIMAL_NORMAL = 1;

const int UA_CURVE_BASIS_POLYNOMIAL = 0;

const int UA_SIGNATURE_FORMAT_ASIC_E = 3;

const int UA_SIGNATURE_FORMAT_ASIC_S = 2;

const int UA_SIGNATURE_FORMAT_CADES = 0;

const int UA_SIGNATURE_FORMAT_XADES = 1;

const int UA_SIGNATURE_HASH_DSTU7564 = 0;

const int UA_SIGNATURE_HASH_GOST34311 = 1;

const int UA_SIGNATURE_LEVEL_B = 0;

const int UA_SIGNATURE_LEVEL_LT = 2;

const int UA_SIGNATURE_LEVEL_T = 1;

/// Bytes the library hands out: the caller owns them and releases them with `ua_free_buffer`. Empty bytes have a
/// NULL `data`. A function writes its output buffers only when it returns `UA_STATUS_OK`.
final class UaBuffer extends ffi.Struct {
  /// The first byte, or NULL when empty.
  external ffi.Pointer<ffi.Uint8> data;

  /// The number of bytes.
  @ffi.Size()
  external int len;

  static ffi.Pointer<UaBuffer> $allocate(
    ffi.Allocator $allocator, {
    required ffi.Pointer<ffi.Uint8> data,
    required int len,
  }) => $allocator<UaBuffer>()
    ..ref.data = data
    ..ref.len = len;
}

/// Bytes the caller lends for one call. A NULL `data` with `len` 0 is empty; an optional input is absent when
/// `data` is NULL.
final class UaBytes extends ffi.Struct {
  /// The first byte.
  external ffi.Pointer<ffi.Uint8> data;

  /// The number of bytes.
  @ffi.Size()
  external int len;

  static ffi.Pointer<UaBytes> $allocate(
    ffi.Allocator $allocator, {
    required ffi.Pointer<ffi.Uint8> data,
    required int len,
  }) => $allocator<UaBytes>()
    ..ref.data = data
    ..ref.len = len;
}

/// A recommended curve of DSTU 4145-2002: its table and the degree m of its field.
final class UaCurve extends ffi.Struct {
  /// Table Г.1 or Г.2.
  @UaCurveBasis()
  external int basis;

  /// The degree m of GF(2^m).
  @ffi.Uint32()
  external int m;

  static ffi.Pointer<UaCurve> $allocate(ffi.Allocator $allocator, {required int basis, required int m}) =>
      $allocator<UaCurve>()
        ..ref.basis = basis
        ..ref.m = m;
}

/// The table of DSTU 4145-2002, Appendix Г a curve comes from: `UA_CURVE_BASIS_POLYNOMIAL` (Г.1) or
/// `UA_CURVE_BASIS_OPTIMAL_NORMAL` (Г.2).
typedef UaCurveBasis = ffi.Uint32;
typedef DartUaCurveBasis = int;

/// A hash fed with a message in parts; made by `ua_gost34311_begin_hash` or `ua_dstu7564_begin_hash`, released
/// by `ua_end_hash` or `ua_free_hash_state`.
final class UaHashState extends ffi.Opaque {}

/// A new key store with one DSTU 4145 key on a curve of table Г.1 and its self-signed certificate.
final class UaKeyStoreRequest extends ffi.Struct {
  /// The subject, e.g. "CN=Name,O=Organization,C=UA".
  external ffi.Pointer<ffi.Char> subject;

  /// The alias of the key entry; NULL: "key".
  external ffi.Pointer<ffi.Char> alias;

  /// The degree m of the curve of table Г.1; 257 is the one of the national PKI.
  @ffi.Uint32()
  external int m;

  /// How many days the certificate is valid.
  @ffi.Uint32()
  external int validity_days;

  /// The hash the certificate is signed over.
  @UaSignatureHash()
  external int signature_hash;

  static ffi.Pointer<UaKeyStoreRequest> $allocate(
    ffi.Allocator $allocator, {
    required ffi.Pointer<ffi.Char> subject,
    required ffi.Pointer<ffi.Char> alias,
    required int m,
    required int validity_days,
    required int signature_hash,
  }) => $allocator<UaKeyStoreRequest>()
    ..ref.subject = subject
    ..ref.alias = alias
    ..ref.m = m
    ..ref.validity_days = validity_days
    ..ref.signature_hash = signature_hash;
}

/// A file lent for one call: its name (UTF-8, NUL-terminated) and its content.
final class UaNamedBytes extends ffi.Struct {
  /// The file name, as a XAdES reference or an ASiC entry names it.
  external ffi.Pointer<ffi.Char> name;

  /// The content.
  external UaBytes content;
}

/// A signature format: `UA_SIGNATURE_FORMAT_CADES`, `_XADES`, `_ASIC_S` or `_ASIC_E`.
typedef UaSignatureFormat = ffi.Uint32;
typedef DartUaSignatureFormat = int;

/// The hash of a PKI signature: `UA_SIGNATURE_HASH_DSTU7564` (DSTU 7564-256) or `UA_SIGNATURE_HASH_GOST34311`.
typedef UaSignatureHash = ffi.Uint32;
typedef DartUaSignatureHash = int;

/// A signature level: `UA_SIGNATURE_LEVEL_B`, `_T` or `_LT`.
typedef UaSignatureLevel = ffi.Uint32;
typedef DartUaSignatureLevel = int;

/// How `ua_sign` signs.
final class UaSigningOptions extends ffi.Struct {
  /// The format.
  @UaSignatureFormat()
  external int format;

  /// B, T (asks the time-stamping service) or LT (also OCSP and caIssuers).
  @UaSignatureLevel()
  external int level;

  /// The hash of the signature.
  @UaSignatureHash()
  external int hash;

  /// CAdES without the data.
  @ffi.Bool()
  external bool is_detached;

  /// CAdES and ASiC-S: also time-stamp the data itself.
  @ffi.Bool()
  external bool has_content_time_stamp;

  /// The time-stamping service URL; NULL: the one the signer's certificate names.
  external ffi.Pointer<ffi.Char> tsa_url;

  /// The OCSP responder URL for every certificate; NULL: each certificate's own.
  external ffi.Pointer<ffi.Char> ocsp_url;

  static ffi.Pointer<UaSigningOptions> $allocate(
    ffi.Allocator $allocator, {
    required int format,
    required int level,
    required int hash,
    required bool is_detached,
    required bool has_content_time_stamp,
    required ffi.Pointer<ffi.Char> tsa_url,
    required ffi.Pointer<ffi.Char> ocsp_url,
  }) => $allocator<UaSigningOptions>()
    ..ref.format = format
    ..ref.level = level
    ..ref.hash = hash
    ..ref.is_detached = is_detached
    ..ref.has_content_time_stamp = has_content_time_stamp
    ..ref.tsa_url = tsa_url
    ..ref.ocsp_url = ocsp_url;
}

/// How a call ended. On anything but `UA_STATUS_OK`, the call's `error_message` holds the refusal in UTF-8.
enum UaStatus {
  /// Done; the outputs are written.
  UA_STATUS_OK(0),

  /// An argument is NULL, not UTF-8, of a wrong length, or a name or number the library does not know.
  UA_STATUS_INVALID_ARGUMENT(1),

  /// A key store, certificate or signature does not parse.
  UA_STATUS_UNREADABLE_INPUT(2),

  /// The key store or its key does not open with the password.
  UA_STATUS_WRONG_PASSWORD(3),

  /// An authenticated ciphertext or a wrapped key is not the one tagged.
  UA_STATUS_AUTHENTICATION_FAILED(4),

  /// A time-stamping, OCSP or certificate download service failed.
  UA_STATUS_SERVICE_FAILURE(5),

  /// A defect of the library: the call panicked; the message says no more.
  UA_STATUS_INTERNAL(6);

  final int value;
  const UaStatus(this.value);

  static UaStatus fromValue(int value) => switch (value) {
    0 => UA_STATUS_OK,
    1 => UA_STATUS_INVALID_ARGUMENT,
    2 => UA_STATUS_UNREADABLE_INPUT,
    3 => UA_STATUS_WRONG_PASSWORD,
    4 => UA_STATUS_AUTHENTICATION_FAILED,
    5 => UA_STATUS_SERVICE_FAILURE,
    6 => UA_STATUS_INTERNAL,
    _ => throw ArgumentError('Unknown value for UaStatus: $value'),
  };
}
